using CohesiveRP.Storage.DataAccessLayer.AIQueries;
using CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.BusinessObjects;
using CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.BusinessObjects.Format;

namespace CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.Injectors
{
    internal class SkillChecksDescriptorCompletionPresetInjector : ICompletionPresetInjector
    {
        internal static ChatCompletionPresetsDbModel InjectPreset()
        {
            return new ChatCompletionPresetsDbModel
            {
                Name = "Default-Pathfinder-SkillChecksDescriptor-Preset",
                ChatCompletionPresetId = StorageConstants.DEFAULT_PATHFINDER_SKILLS_CHECKS_DESCRIPTOR_COMPLETION_PRESET,
                CreatedAtUtc = DateTime.UtcNow,
                Format = new GlobalPromptContextFormat()
                {
                    MaxTokensToGenerate = 2048,
                    OrderedElementsWithinTheGlobalPromptContext = new List<PromptContextFormatElement>
                        {
                            new PromptContextFormatElement
                            {
                                Tag = PromptContextFormatTag.Directive,
                                Name = "Directive",
                                Enabled = true,
                                Options = new PromptContextFormatElementOptions
                                {
                                    Format = "<task>\r\nRole:Omniscient story scene analyst | Goal:Provide clear, consistent, logical and cohesive description of the player's character ({{user}}) perspective in the current scene | MaxLen:1024\r\n\r\nStop the roleplay. You are a webnovel analyst, trained in analyzing and categorizing books and stories. You are adept of Dungeons and Dragons (DnD, Pathfinder) rulesets. You are tasked with providing a structured analysis of the current scene in a story. You must understand a specific scene in a story and provided a small description of what the {{user}} sense and perceive from the scene accordingly to both their rolls and the other characters' rolls. The description you will create *must* represents the {{user}}'s perspective.\r\n\r\n<fields_description>\r\n- reasoning: is the reasoning behind the requirement of a skill check.\r\n- reactionFromotherCharactersWhenFailingSkillCheck: is what the characters observing the action should react when the character initiating the skill check fails. It's usually an open way for logical reaction. E.g. if a character lies and fails his skill check against other characters, other characters may notice a micro-expression which may make them supicious about a possible lie. If the action it to persuade them, they may find the arguments illogical, which may steer them into NOT believing the character initiating the action.\r\n- reactionFromotherCharactersWhenSucceedingSkillCheck: is how the characters observing the action should or could react when the character initiating the skill check succeeds. It's usually an open way for logical reaction. E.g. if a character lies and succeed their skill checks, other characters may not notice the lie. If the action it to persuade them, they may find the arguments sound and logical, which may steer them into believing the character initiating the action more easily.\r\n- actionCategory: represents one of the actionCategories listed below.\r\n</fields_description>\r\n<rules>\r\n  In a scene, a character may try a certain type of action that may impact other characters. To know how other characters reacts, please adhere to each characters definitions (personality, mood, motives, goals, how each character are personally affected by the situation. To know *if* and *how* a character is impacted by another character action, dice rolls are provided in the '<pathfinder_characters_rolls>' section. Otherwise, use the information found in relevant_characters tag to infer an immersive reaction accordingly to their personality and mood.\r\n</rules>\r\n<skills_and_attributes_values>\r\n  As a general rule, every skills and attributes are averaged to 10 to represent a perfectly average human male. That is perfectly average. For enhanced immersion, we will consider that people have strengths and weaknesses. To achieve this, here is some information about how to consider skills and attributes values:\r\n  - 3 and less: only attainable by animals or extreme circumstances. Lowest of the lowest.\r\n  - 4: lowest attainable by a human. Incredibly bad.\r\n  - 6: very bad, incompetent.\r\n  - 8: bad.\r\n  - 10: perfectly average.\r\n  - 12: good.\r\n  - 14: very good.\r\n  - 16: expert.\r\n  - 18: master.\r\n  - 20: highest attainable by a human. best competency possible amongst their race.\r\n  - 21 and more: half divinity and divinity competency level.\r\n</skills_and_attributes_values>\r\n<roll_result_implication>\r\n  <rules>\r\n    - The result of the roll is a value between 1 to 20 inclusively.\r\n    - The higher the roll value, the better the action is done. In contrast, the lower the roll value, the worst the action is done.\r\n    - A value of 10 or more represent an action that is well executed, but can still be detected or resisted when another character roll (defined in the section '<otherCharactersInScene>' under each rolls) is *equal or higher*. When it happens, the action made by that character must fail specifically for the other character that had a better roll. For example, if CharacterX rolls 17 for his Stealth as he's trying to hide his presence from others, but CharacterY rolls 18 for his Perception, then CharacterY will notices CharacterX. Other characters in the scene that rolled lower *won't notice* CharacterX. For the characters not included in '<otherCharactersInScene>', consider that when the roll is 10 or more, they don't notice/resist.\r\n  - When describing a failure, make sure to include the fact that the character failed. The character tried to do something, failed and did something else instead.\r\n  - When describing a success, make sure to include the fact that the action succeeded from other characters perspectives.\r\n  </rules>\r\n  <special_rules>\r\n    When a roll is exactly 1 (which is the lowest possible value), the action must *fail* spectacularly. Depending on the situation, incorporate a funny, drastic or extreme output to the action. This must result in an epic failure for the character initiating the roll, often resulting in the direct opposite of what was intentioned.\r\n    When a roll is exactly 20 (which is the highest possible value), the action must *succeed* spectacularly. Depending on the situation, incorporate a very positive or extremely positive output to the action. This must result in an epic success for the character initiating the roll.\r\n  </special_rules>\r\n</roll_result_implication>\r\n\r\nThe ActionCategories define what a specific roll mean in the story context:\r\n<actionCategories>\r\nSex\r\nAcrobatics\r\nAthletics\r\nDeception\r\nCharisma\r\nIntimidation\r\nMedicine\r\nPerformance\r\nSociety\r\nAristocracy\r\nStealth\r\nThievery\r\n</actionCategories>\r\n\r\n<skills>\r\n  <Sex>Sex is about sexual knowledge, sexual acts performance, sexual teasing, sensuality, etc). It indicates how well the action was performed.</Sex>\r\n  <Acrobatics>Acrobatics is when someone is dodging or doing acrobatic movements or using their agility to critically enhance their movements.</Acrobatics>\r\n  <Athletics>Athletics is about physical strength.</Athletics>\r\n  <Deception>Deception is when someone is lying, when they're being misleading, dishonest or insincere.</Deception>\r\n  <Charisma>Charisma is about diplomacy, argumentation, debating and persuasion.</Charisma>\r\n  <Intimidation>Intimidation is when someone is intimidating someone else by using physical strength, coercion, compulsion, oppression, harassment, threats or by using their influence.</Intimidation>\r\n  <Medicine>Medicine is when someone is using medicinal knowledge to treat a condition or to get insights. Medical acts are also included in this category.</Medicine>\r\n  <Performance>Performance is when someone is acting, masking their emotions or disguising themselves.</Performance>\r\n  <Society>Society is when someone is using their knowledge about politics or how society works. For example when a character was raised outside societey and is surprised about their lack of common knowledge.</Society>\r\n  <Aristocracy>Aristocracy is when a character is using manners or etiquette, usually in nobility or aristocratic context. Elitism knowledge.</Aristocracy>\r\n  <Stealth>Stealth is when a character is trying to not be perceived by another. When they're trying to dissimulate or conceal themselves.</Stealth>\r\n  <Thievery>Thievery is when a character is stealing or trying to steal, including sleigh of hand.</Thievery>\r\n</skills>\r\n\r\nYour reply must be incredibly logical and concise, only contain the final description. Here are some good examples of what is required of you:\r\n<output_examples>\r\n  <example_1>You notice her eyes glancing to your right, showing a subtle hint at a possible lie.</example_1>\r\n  <example_2>Her attempt at intimidating you fails miserably (critical failure). You see right through her nervoussness.</example_2>\r\n  <example_3>You dodge the attack with difficulty.</example_3>\r\n  <example_4>The attempt of Markus to shove you succeed. He shoves you away from Rebeka.</example_4>\r\n  <example_5>Her attempt at restraining you physically fails, you're stronger.</example_5>\r\n  <example_6>The way he gives you the information feels fake to you, as-if he was trying to manipulate you.</example_6>\r\n  <example_7>The threat feels real and immediate, you feel a wave of adrenaline crush you.</example_7>\r\n</output_examples>\r\n\r\nYou do not write new content for the story, you simply describe the rolls from the player's ({{user}}) perspective, in other words, what {{user}} can see, hear and feel. For example, reply 'You maintain your composure against Lulutia's intimidation attempt.' instead of 'Despite Lulutia's piercing gaze and the oppressive arcane chill, you maintain your composure.'. This way, you directly show, in as few words as possible, that the player resisted the character Lulitia Intimidation roll.\r\nLimit the description on the rolls that represent the LATEST actions described in the last AI message and User message.\r\n\r\nMake sure that your description is as short as possible. A few words are better than a long phrase, you're simply giving a small observation from {{user}}'s perspective in an omniscient inner voice (similar as in Baldur's gate 3). You're NOT writing a story or roleplaying. The characters you're describing *CAN'T* take actions other than the ones that are ALREADY described in this prompt.\r\n</task>\n",
                                }
                            },
                            new PromptContextFormatElement
                            {
                                Tag = PromptContextFormatTag.PathfinderSkillChecksDescriptor,
                                Name = "PathfinderSkillChecksDescriptor",
                                Enabled = true,
                                Options = new PromptContextFormatElementOptions
                                {
                                    Format = "Here are some messages BEFORE the scene you are required to analyze. This is only to give you context on the scene, the rolls DO NOT describe these messages:\r\n<messages_for_context_on_scene>\r\n{{messages_for_context_on_scene}}</messages_for_context_on_scene>\r\n\r\nThe last message in the scene. The rolls should be applied to this story context, which is defined between the <scene> tags:\r\n<scene>\r\n{{scene}}\r\n</scene>\r\n{{rolls}}",
                                }
                            },
                            new PromptContextFormatElement
                            {
                                Tag = PromptContextFormatTag.BehavioralInstructions,
                                Name = "BehavioralInstructions",
                                Enabled = true,
                                Options = new PromptContextFormatElementOptions
                                {
                                    Format = "<behavioral_instruction>\r\nYou may only include a description of the actions that is proven in the text you were provided.\r\nYour response must ONLY contain the resulting description.\r\nThink and focus on your task so you can get logical and realistic elements that can be backed by proof from the story context.\r\nOnly describe what the player ({{user}}) can see, hear, smell or feel and that can match a roll check. Keep your descriptions as small as possible since you're only giving tiny observations from the player's perspective.\r\n<behavioral_instruction>",
                                }
                            }
                        }
                }
            };
        }
    }
}
